commands.command:
$ErrorActionPreference = 'Stop'
New-Item -ItemType Directory -Force -Path 'captures' | Out-Null
Set-Content -LiteralPath 'captures/001-read-skill.stderr.txt' -Value '' -NoNewline
try {
  Get-Content -Raw -LiteralPath 'skills/researching-characters/SKILL.md' | Tee-Object -FilePath 'captures/001-read-skill.stdout.txt'
  exit 0
} catch {
  $_ | Out-String | Set-Content -LiteralPath 'captures/001-read-skill.stderr.txt'
  exit 1
}

$ErrorActionPreference = 'Stop'
Set-Content -LiteralPath 'captures/002-read-research-contract.stderr.txt' -Value '' -NoNewline
try {
  Get-Content -Raw -LiteralPath 'skills/researching-characters/references/research-contract.md' | Tee-Object -FilePath 'captures/002-read-research-contract.stdout.txt'
  exit 0
} catch {
  $_ | Out-String | Set-Content -LiteralPath 'captures/002-read-research-contract.stderr.txt'
  exit 1
}

$ErrorActionPreference = 'Stop'
Set-Content -LiteralPath 'captures/003-verify-artifacts.stderr.txt' -Value '' -NoNewline
try {
  $report = Get-Content -Raw -LiteralPath 'agent-report.json' | ConvertFrom-Json
  $final = Get-Content -Raw -LiteralPath 'final.md'
  if ($report.schema_version -ne '1.0' -or $report.case_id -ne 'ambiguous-character-stop' -or $report.variant -ne 'skill-enabled' -or $report.final_file -ne 'final.md') { throw 'Required report fields are invalid.' }
  if ([string]::IsNullOrWhiteSpace($final)) { throw 'final.md is empty.' }
  [pscustomobject]@{ report_json_valid = $true; required_fields_present = $true; final_nonempty = $true } | ConvertTo-Json -Compress | Tee-Object -FilePath 'captures/003-verify-artifacts.stdout.txt'
  exit 0
} catch {
  $_ | Out-String | Set-Content -LiteralPath 'captures/003-verify-artifacts.stderr.txt'
  exit 1
}
